function sprite(name:string,x:number,y:number,size:number,alpha=1,angle=0,team?:number){const a=team===undefined?image(name):powerImage(name,team);if(!a)return;c.save();c.globalAlpha=alpha;c.translate(x,y);if(angle)c.rotate(angle);c.drawImage(a,-size/2,-size/2,size,size);c.restore();}
