function drawCoveredUnit(u:CrucibleUnit){if(u.x*view.scale+view.x< -180||u.x*view.scale+view.x>view.w+180||u.y*view.sy+view.y< -180||u.y*view.sy+view.y>view.h+180)return;const covered=game.terrain.foreground.filter(s=>u.y<s.depth&&u.x+100>s.left&&u.x-100<s.right&&u.y>s.top&&u.y-160<s.bottom);if(!covered.length){drawUnit(u);return;}c.save();for(const s of covered){c.beginPath();c.rect(-10000,-10000,20000,20000);s.points.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();c.clip('evenodd');}drawUnit(u);c.restore();if(u.team===game.controlled){c.save();c.globalAlpha=.25;drawUnit(u);c.restore();}}
