function sightPath(unit:CrucibleUnit,radius:number,points:number[][]|null){if(points){points.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.closePath();}else{c.moveTo(unit.x+radius,unit.y);c.arc(unit.x,unit.y,radius,0,Math.PI*2);}}
