  for(const w of b.cyclones)fx('lycanthrope-cyclone',w.x,w.y-w.radius*.5,w.radius*2.3,.85,Math.cos(w.angle)*.08);
  for(const w of b.scytheWaves)fx('reaper-wave',w.x,w.y,w.width*3.2,.8,w.rotation);
