  for(const f of b.fissures){const x=(f.x+f.endX)/2,y=(f.y+f.endY)/2,source=powerImage('titan-fissure',team);if(source&&visible(x,y,f.length)){c.save();c.translate(x,y);c.rotate(f.angle);c.globalAlpha=.7;c.drawImage(source,-f.length/2,-f.width,f.length,f.width*2);c.restore();}}
  const aliases:Record<string,string>={claw:b.monster.id==='titan'?'titan-cleave':b.monster.id==='lycanthrope'?'lycanthrope-claw':'devourer-claw',blood:'enemy-hit',release:CHAMPION_VFX[b.monster.id].unbound,rupture:'titan-cleave',shockwave:'titan-cleave',blast:b.monster.id,catastrophe:'calamity',meteor:'calamity-starfall-preview',vortex:'calamity-vortex-preview',frenzy:'devourer-frenzy',feast:'devourer-frenzy',devour:'devourer',execute:'devourer-claw',lunge:'devourer-dodge',charge:'titan-cleave',launch:'titan-cleave',curse:'overlord-soul-brand',corruption:'overlord-soul-brand',dominate:'overlord',dominion:'overlord',summon:'overlord',servant:'overlord-soul-brand',beam:b.monster.id};
  // Limit brief hit overlays; persistent fields/projectiles above retain their real geometry.
