let joystick={x:0,y:0},joystickPointer:number|null=null;const pad=$('pad');function release(event?:PointerEvent){if(event&&event.pointerId!==joystickPointer)return;const owner=joystickPointer;joystickPointer=null;joystick={x:0,y:0};$('stick').style.transform='';if(owner!==null&&pad.hasPointerCapture(owner))pad.releasePointerCapture(owner);}pad.onpointerdown=e=>{if(joystickPointer!==null)return;e.preventDefault();joystickPointer=e.pointerId;pad.setPointerCapture(e.pointerId);stick(e);};function stick(e:PointerEvent){const box=pad.getBoundingClientRect(),x=(e.clientX-box.x-box.width/2)/(box.width*.35),y=(e.clientY-box.y-box.height/2)/(box.height*.35),d=Math.max(1,Math.hypot(x,y));joystick={x:x/d,y:y/d};$('stick').style.transform='translate('+joystick.x*box.width*.28+'px,'+joystick.y*box.height*.28+'px)';}pad.onpointermove=e=>{if(e.pointerId===joystickPointer)stick(e);};pad.onpointerup=pad.onpointercancel=pad.onlostpointercapture=release;

window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('battle-setup').hidden||$<HTMLDialogElement>('battle-result').open)return;e.preventDefault();if(e.repeat)return;pendingSlot=null;placementFeedback='';if(!$('shop').hidden){closeShop();return;}$('pause').click();return;}if(!$('battle-setup').hidden)return;if(!$('shop').hidden){if(e.key==='Escape')closeShop();return;}if((e.target as HTMLElement).matches('input,select,summary')||((e.target as HTMLElement).matches('button')&&[' ','Enter'].includes(e.key)))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='m'&&!e.repeat){toggleMap();return;}keys.add(e.key.toLowerCase());if(!e.repeat&&!paused&&game.controlled>=0){const slot=({'q':0,'e':1,'r':2,' ':3,'1':0,'2':1,'3':2,'4':3} as Record<string,number>)[e.key.toLowerCase()];if(slot!==undefined)activate(slot);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',e=>{if(e.target!==window)return;keys.clear();release();requestAnimationFrame(()=>{if(!document.hasFocus()&&!document.activeElement?.matches('select,input')){paused=true;syncPauseButton();}});});document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;keys.clear();release();$('pause').textContent='Resume';}else{last=performance.now();frames=[];}});
