async function toggleFullscreen(){const doc=document as Document&{webkitFullscreenElement?:Element;webkitExitFullscreen?:()=>Promise<void>},root=document.documentElement as HTMLElement&{webkitRequestFullscreen?:()=>Promise<void>};try{if(doc.fullscreenElement||doc.webkitFullscreenElement){await (doc.exitFullscreen?.()||doc.webkitExitFullscreen?.());}else{if(root.requestFullscreen)await root.requestFullscreen({navigationUI:'hide'});else if(root.webkitRequestFullscreen)await root.webkitRequestFullscreen();else throw Error('Fullscreen is unavailable');try{await (screen.orientation as ScreenOrientation&{lock?:(mode:string)=>Promise<void>}).lock?.('landscape');}catch{}$('screen-help').hidden=true;}}catch{$('screen-help').hidden=false;}syncFullscreen();}
