async function readArtwork(path:string){let error:unknown;for(let attempt=0;attempt<3;attempt++){const image=new Image();image.src=path+'?v='+BUILD_VERSION+(attempt?'&retry='+attempt:'');try{await image.decode();return image;}catch(e){error=e;image.src='';if(attempt<2)await new Promise(resolve=>setTimeout(resolve,150*(attempt+1)));}}throw Error(path+': '+String(error));}
